SELECT COUNT(1)
FROM t_wallet_account


        AND (wallet_account_no = #{keyword} OR owner_name LIKE CONCAT('%', #{keyword}, '%'))


        AND owner_type = #{ownerType}


        AND account_status = #{accountStatus}

SELECT *
FROM t_wallet_account


        AND (wallet_account_no = #{keyword} OR owner_name LIKE CONCAT('%', #{keyword}, '%'))


        AND owner_type = #{ownerType}


        AND account_status = #{accountStatus}


ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT *
FROM t_wallet_account
WHERE wallet_owner_id = #{walletOwnerId}
  AND account_type = #{accountType}
  AND account_scene = #{accountScene}

SELECT * FROM t_wallet_account WHERE wallet_account_no IN
#{item}
ORDER BY created_at DESC

SELECT *
FROM t_wallet_flow


        AND wallet_account_no = #{walletAccountNo}


        AND source_system = #{sourceSystem}


        AND source_biz_no = #{sourceBizNo}


ORDER BY created_at DESC, id DESC

SELECT *
FROM t_wallet_flow
WHERE wallet_account_no = #{walletAccountNo}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT *
FROM t_wallet_account_status_log
WHERE wallet_account_no = #{walletAccountNo}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO t_wallet_account(
    wallet_account_no, wallet_owner_id, owner_type, owner_name, account_type, account_scene, currency_code,
    account_status, allow_credit, risk_level, total_balance, available_balance, frozen_balance,
    pending_in_balance, pending_out_balance, opened_at, closed_at
) VALUES (
    #{walletAccountNo}, #{walletOwnerId}, #{ownerType}, #{ownerName}, #{accountType}, #{accountScene}, #{currencyCode},
    #{accountStatus}, #{allowCredit}, #{riskLevel}, #{totalBalance}, #{availableBalance}, #{frozenBalance},
    #{pendingInBalance}, #{pendingOutBalance}, #{openedAt}, #{closedAt}
)

INSERT INTO t_wallet_flow(
    flow_no, wallet_account_no, flow_type, source_system, source_biz_no, idempotency_key,
    change_amount, before_available_balance, after_available_balance, operator_name, operation_reason
) VALUES (
    #{flowNo}, #{walletAccountNo}, #{flowType}, #{sourceSystem}, #{sourceBizNo}, #{idempotencyKey},
    #{changeAmount}, #{beforeAvailableBalance}, #{afterAvailableBalance}, #{operatorName}, #{operationReason}
)

INSERT INTO t_wallet_account_status_log(
    wallet_account_no, before_status, after_status, reason_code, reason_desc, operator_id, operator_name
) VALUES (
    #{walletAccountNo}, #{beforeStatus}, #{afterStatus}, #{reasonCode}, #{reasonDesc}, #{operatorId}, #{operatorName}
)

mapper.update:
UPDATE t_wallet_account
SET account_status = #{accountStatus},
    closed_at = #{closedAt},
    updated_at = CURRENT_TIMESTAMP
WHERE wallet_account_no = #{walletAccountNo}
  AND account_status = #{currentStatus}
